func (e *FeTileElement) Render(w io.Writer) error {
	if e.skipRender {
		return nil
	}

	if e.attributes.Len() == 0 {
		if _, err := io.WriteString(w, "<feTile>"); err != nil {
			return err
		}
	} else {
		if _, err := io.WriteString(w, "<feTile"); err != nil {
			return err
		}
		if _, err := e.attributes.WriteTo(w); err != nil {
			return err
		}
		if _, err := io.WriteString(w, ">"); err != nil {
			return err
		}
	}

	for _, child := range e.children {
		if err := child.Render(w); err != nil {
			return err
		}
	}

	_, err := io.WriteString(w, "</feTile>")
	return err
}
